test.query:
s=$(date +%s%N)
${CLICKHOUSE_CLIENT} --allow_insert_into_iceberg 1 --allow_experimental_iceberg_compaction 1 --iceberg_insert_max_rows_in_data_file 1000000 --max_insert_threads 1 --optimize_trivial_count_query 0 --query "
    DROP TABLE IF EXISTS icp_opt_run SYNC;
    CREATE TABLE icp_opt_run (l_orderkey Int32, l_partkey Int32, l_quantity Float64, l_extendedprice Float64, l_shipdate Date, l_tag Int32) ENGINE = IcebergS3(perf_s3, filename = 'iceberg_compaction_opt_$s/');
    INSERT INTO icp_opt_run SELECT l_orderkey, l_partkey, l_quantity, l_extendedprice, l_shipdate, 0 FROM tpch10.lineitem WHERE l_orderkey % 10 = 0;
    INSERT INTO icp_opt_run SELECT l_orderkey, l_partkey, l_quantity, l_extendedprice, l_shipdate, 1 FROM tpch10.lineitem WHERE l_orderkey % 100 = 1;
    DELETE FROM icp_opt_run WHERE l_tag = 1;
    OPTIMIZE TABLE icp_opt_run;
    SELECT throwIf(countIf(content = 1) != 0 OR (SELECT count() FROM icp_opt_run) != (SELECT count() FROM tpch10.lineitem WHERE l_orderkey % 10 = 0)) FROM system.iceberg_files WHERE database = 'default' AND table = 'icp_opt_run';
    DROP TABLE icp_opt_run SYNC"

s=$(date +%s%N)
${CLICKHOUSE_CLIENT} --allow_insert_into_iceberg 1 --iceberg_insert_max_rows_in_data_file 1000000 --max_insert_threads 1 --optimize_trivial_count_query 0 --query "
    DROP TABLE IF EXISTS icp_ref_run SYNC;
    CREATE TABLE icp_ref_run (l_orderkey Int32, l_partkey Int32, l_quantity Float64, l_extendedprice Float64, l_shipdate Date, l_tag Int32) ENGINE = IcebergS3(perf_s3, filename = 'iceberg_compaction_ref_$s/');
    INSERT INTO icp_ref_run SELECT l_orderkey, l_partkey, l_quantity, l_extendedprice, l_shipdate, 0 FROM tpch10.lineitem WHERE l_orderkey % 10 = 0;
    INSERT INTO icp_ref_run SELECT l_orderkey, l_partkey, l_quantity, l_extendedprice, l_shipdate, 1 FROM tpch10.lineitem WHERE l_orderkey % 100 = 1;
    DELETE FROM icp_ref_run WHERE l_tag = 1;
    SELECT throwIf(count() != (SELECT count() FROM tpch10.lineitem WHERE l_orderkey % 10 = 0)) FROM icp_ref_run;
    DROP TABLE icp_ref_run SYNC"
